    total_sensors = 48

    with ProcessPoolExecutor(max_workers=None) as executor:
        # Submitte alle Tasks
        futures = {}
        for sens_id in range(48):
            future = executor.submit(
                process_sensor,
                sens_id, ltr_data, curr_list, mag_data,
                magsens_positions, steps_xy, steps_z, offs_xy, offs_z
            )
            futures[future] = sens_id

        # Verarbeite Ergebnisse mit Progress Bar
        with tqdm(total=total_sensors, desc="Processing sensors", unit="sensor") as pbar:
            for future in as_completed(futures):
                sens_id, offset_result, result_str = future.result()
                offs_results.append((sens_id, offset_result))

                # Zeige das Ergebnis unter der Progress Bar
                tqdm.write(result_str)

                # Update Progress Bar
                pbar.update(1)

    # Sortiere nach sens_id
    offs_results.sort(key=lambda x: x[0])
    offs_list = [r[1] for r in offs_results]

    print("\n" + "=" * 80)
